practical.solution:
@OptIn(FlowPreview::class, ExperimentalCoroutinesApi::class)
class SearchViewModel(
    private val repository: SearchRepository,
    private val savedState: SavedStateHandle
) : ViewModel() {
    // SavedStateHandle restores the query after rotation and process death.
    private val query: StateFlow<String> = savedState.getStateFlow("query", "")

    private val results: Flow<SearchUiState> = query
        .debounce(300)
        .map { it.trim() }
        .distinctUntilChanged()
        .flatMapLatest { text -> // Cancels the previous search when a new query arrives.
            if (text.isEmpty()) flowOf(SearchUiState())
            else flow {
                emit(SearchUiState(loading = true))
                emit(SearchUiState(results = repository.search(text)))
            }.catch { e -> emit(SearchUiState(error = e.message ?: "Search failed")) }
            // catch is inside flatMapLatest so one failure does not end the outer flow.
        }

    // The text field shows the latest typed text immediately, not the debounced value.
    val state: StateFlow<SearchUiState> = combine(query, results.onStart { emit(SearchUiState()) }) { text, result ->
        result.copy(query = text)
    }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), SearchUiState())

    fun onQueryChange(text: String) {
        savedState["query"] = text
    }
}

