practical.solution:
sealed class FeedState {
    object Loading : FeedState()
    data class Content(val items: List<String>, val refreshing: Boolean = false, val message: String? = null) : FeedState()
    data class Error(val message: String) : FeedState()
}

sealed class FeedEvent {
    object Refresh : FeedEvent()
    data class Loaded(val items: List<String>) : FeedEvent()
    data class Failed(val message: String) : FeedEvent()
    object MessageShown : FeedEvent()
}

fun reduce(state: FeedState, event: FeedEvent): FeedState = when (event) {
    FeedEvent.Refresh -> if (state is FeedState.Content) state.copy(refreshing = true) else FeedState.Loading
    is FeedEvent.Loaded -> FeedState.Content(event.items)
    // Keep content the user can already see; a full-screen error would hide it.
    is FeedEvent.Failed -> if (state is FeedState.Content) state.copy(refreshing = false, message = event.message) else FeedState.Error(event.message)
    FeedEvent.MessageShown -> if (state is FeedState.Content) state.copy(message = null) else state
}

practical.harness:
fun practicalCheck(n: Int, expected: Any?, actual: () -> Any?) {
    val result = try { actual() } catch (e: Throwable) { "threw ${e.javaClass.simpleName}" }
    println(if (result == expected) "PASS $n" else "FAIL $n: expected $expected but was $result")
}

fun main() {
    val content = FeedState.Content(listOf("a", "b"))
    practicalCheck(1, FeedState.Content(listOf("a", "b"), refreshing = true)) { reduce(content, FeedEvent.Refresh) }
    practicalCheck(2, FeedState.Loading) { reduce(FeedState.Error("offline"), FeedEvent.Refresh) }
    practicalCheck(3, FeedState.Content(listOf("c"))) { reduce(FeedState.Content(listOf("a"), refreshing = true, message = "old"), FeedEvent.Loaded(listOf("c"))) }
    practicalCheck(4, FeedState.Content(listOf("a", "b"), message = "offline")) { reduce(content.copy(refreshing = true), FeedEvent.Failed("offline")) }
    practicalCheck(5, FeedState.Error("offline")) { reduce(FeedState.Loading, FeedEvent.Failed("offline")) }
    practicalCheck(6, content) { reduce(content.copy(message = "offline"), FeedEvent.MessageShown) }
}

practical.starter:
// Notes are edited offline and saved in Room. Write the code that syncs them to the server.
// Requirements:
// - Sync only with a network connection and when the battery is not low.
// - Run one sync at a time, even if the user edits 20 notes quickly.
// - Edits made while a sync is running must not be lost or wait hours for the next sync.
// - Retry network and 5xx errors with exponential backoff; do not retry 4xx validation errors.
// - Also sync roughly every 6 hours in the background.
// - Uploads must be safe to repeat: a retry after a timeout must not create duplicates.
@Entity
data class NoteEntity(
    @PrimaryKey val id: String,          // Generated on the device
    val body: String,
    val serverVersion: Long,             // Last version acknowledged by the server
    val localRevision: Long,             // Incremented on every local edit
    val dirty: Boolean,
    val failedCode: Int? = null
)

interface NotesApi {
    // Returns the new server version. Throws HttpException or IOException.
    suspend fun upsert(id: String, body: String, baseVersion: Long): Long
}

practical.solution:
@Dao
interface NoteDao {
    @Query("SELECT * FROM NoteEntity WHERE dirty = 1 AND failedCode IS NULL LIMIT 50")
    suspend fun dirtyBatch(): List<NoteEntity>

    // Clears dirty only if the note was not edited again while it was uploading.
    @Query("UPDATE NoteEntity SET dirty = (localRevision != :revision), serverVersion = :version WHERE id = :id")
    suspend fun markSynced(id: String, revision: Long, version: Long)

    @Query("UPDATE NoteEntity SET failedCode = :code WHERE id = :id")
    suspend fun markFailed(id: String, code: Int)
}

// Constructor dependencies need a WorkerFactory (for example @HiltWorker with @AssistedInject).
class SyncNotesWorker(
    context: Context,
    params: WorkerParameters,
    private val dao: NoteDao,
    private val api: NotesApi
) : CoroutineWorker(context, params) {
    override suspend fun doWork(): Result {
        // Keep draining so edits made during this run are uploaded before it finishes.
        while (true) {
            val batch = dao.dirtyBatch()
            if (batch.isEmpty()) return Result.success()
            for (note in batch) {
                try {
                    // The device-generated ID makes the upsert idempotent; baseVersion detects conflicts.
                    val version = api.upsert(note.id, note.body, note.serverVersion)
                    dao.markSynced(note.id, note.localRevision, version)
                } catch (e: HttpException) {
                    val retryable = e.code() >= 500 || e.code() == 408 || e.code() == 429
                    if (retryable) return Result.retry()
                    dao.markFailed(note.id, e.code()) // Show it to the user; retrying cannot fix it.
                } catch (e: IOException) {
                    return Result.retry()
                }
            }
        }
    }
}

object NotesSync {
    private val constraints = Constraints.Builder()
        .setRequiredNetworkType(NetworkType.CONNECTED)
        .setRequiresBatteryNotLow(true)
        .build()

    // Call after every local edit. KEEP ignores requests while a sync is queued or running;
    // the running worker drains new edits because it re-reads dirty notes until none remain.
    fun requestSync(context: Context) {
        val request = OneTimeWorkRequestBuilder<SyncNotesWorker>()
            .setConstraints(constraints)
            .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
            .build()
        WorkManager.getInstance(context).enqueueUniqueWork("notes-sync", ExistingWorkPolicy.KEEP, request)
    }

    // Call once at app start.
    fun schedulePeriodic(context: Context) {
        val request = PeriodicWorkRequestBuilder<SyncNotesWorker>(6, TimeUnit.HOURS)
            .setConstraints(constraints)
            .build()
        WorkManager.getInstance(context)
            .enqueueUniquePeriodicWork("notes-sync-periodic", ExistingPeriodicWorkPolicy.KEEP, request)
    }
}
